import type { AttributeId } from "@/core/types";
import type { EventChoice } from "./events";

/**
 * DM 상대와의 오프라인 만남 시나리오 — 웹소설 형식.
 * - pages: 한 화면씩 넘겨 읽는 장문 본문(합계 1000자 이상). "{name}"은 상대 이름으로 치환.
 * - 마지막 페이지까지 읽으면 choices(선택지)가 나타난다.
 * - attribute가 지정되면 해당 성향 상대에게만 등장(없으면 범용).
 * - adultOnly는 계정 성인물 해제가 켜져 있을 때만 후보.
 * 효과 적용은 systems가 EventEffect 로직을 재사용한다(데이터는 규칙에 비의존).
 */
export interface MeetingScenario {
  id: string;
  emoji: string;
  title: string;
  pages: string[];
  attribute?: AttributeId;
  adultOnly?: boolean;
  /** 성인 트윗 누적(state.adultTweetsPosted)이 이 값 이상일 때만 만남 풀에 등장. 미지정=게이트 없음. */
  minAdultTweets?: number;
  choices: EventChoice[];
}

